import React, { useState } from 'react';
import TopicSuggestions, { detectSuggestions } from './TopicSuggestions';

function TopicCard({ topic, thoughts, books, onSelect, children }) {
  const topicThoughts = thoughts.filter(t => topic.thoughtIds.includes(t.id));
  const bookIds = [...new Set(topicThoughts.map(t => t.bookId))];
  const relatedBooks = bookIds.map(id => books.find(b => b.id === id)).filter(Boolean);
  const lastUpdated = new Date(topic.updatedAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });

  return (
    <div style={{ marginBottom: children ? 0 : 0 }}>
      <div onClick={() => onSelect(topic.id)}
        style={{ background: 'var(--paper-card)', border: '1px solid var(--paper-3)', borderRadius: 10, padding: '14px 16px', cursor: 'pointer', transition: 'box-shadow 0.15s, border-color 0.15s', borderLeft: topic.parentId ? '3px solid var(--paper-3)' : '1px solid var(--paper-3)' }}
        onMouseEnter={e => { e.currentTarget.style.boxShadow = 'var(--shadow-sm)'; e.currentTarget.style.borderColor = 'var(--accent-2)'; }}
        onMouseLeave={e => { e.currentTarget.style.boxShadow = 'none'; e.currentTarget.style.borderColor = topic.parentId ? 'var(--paper-3)' : 'var(--paper-3)'; }}>
        <div style={{ display: 'flex', gap: 5, marginBottom: 8, alignItems: 'center' }}>
          {relatedBooks.map(b => <div key={b.id} title={b.title} style={{ width: 8, height: 8, borderRadius: '50%', background: b.color }} />)}
          {topic.parentId && <span style={{ fontSize: 9, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', textTransform: 'uppercase', letterSpacing: '0.05em', marginLeft: 2 }}>sub-topic</span>}
        </div>
        <div style={{ fontSize: 14, fontWeight: 500, color: 'var(--ink)', marginBottom: 5, lineHeight: 1.35 }}>{topic.title}</div>
        {topic.summary && <p style={{ fontSize: 12, color: 'var(--ink-3)', lineHeight: 1.55, fontStyle: 'italic', marginBottom: 8, display: '-webkit-box', WebkitLineClamp: 2, WebkitBoxOrient: 'vertical', overflow: 'hidden' }}>{topic.summary}</p>}
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <span style={{ fontSize: 10, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal' }}>{bookIds.length} book{bookIds.length !== 1 ? 's' : ''} · {topicThoughts.length} note{topicThoughts.length !== 1 ? 's' : ''}</span>
          <span style={{ marginLeft: 'auto', fontSize: 10, color: 'var(--ink-4)', fontStyle: 'italic' }}>{lastUpdated}</span>
        </div>
      </div>
      {/* Sub-topics */}
      {children && <div style={{ marginLeft: 20, marginTop: 6, display: 'flex', flexDirection: 'column', gap: 6 }}>{children}</div>}
    </div>
  );
}

export default function TopicList({ topics, thoughts, books, onSelect, onCreate, onConfirmSuggestion, dismissedTags, onDismiss }) {
  const [search, setSearch] = useState('');
  const [filterBook, setFilterBook] = useState('all');
  const [showEmpty, setShowEmpty] = useState(true);

  const suggestions = detectSuggestions(thoughts, topics).filter(s => !dismissedTags.includes(s.tag));

  // Filter
  const filtered = topics.filter(t => {
    if (search && !t.title.toLowerCase().includes(search.toLowerCase())) return false;
    if (filterBook !== 'all') {
      const topicThoughts = thoughts.filter(th => t.thoughtIds.includes(th.id));
      if (!topicThoughts.some(th => th.bookId === filterBook)) return false;
    }
    if (!showEmpty && t.thoughtIds.length === 0) return false;
    return true;
  });

  // Build tree: root topics + their sub-topics
  const roots = filtered.filter(t => !t.parentId);
  const getChildren = (parentId) => filtered.filter(t => t.parentId === parentId);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      {/* Topbar */}
      <div style={{ padding: '12px 22px 10px', borderBottom: '1px solid var(--paper-3)', display: 'flex', alignItems: 'center', gap: 10, flexShrink: 0 }}>
        <div>
          <div style={{ fontSize: 15, fontWeight: 500, color: 'var(--ink)' }}>Topic pages</div>
          <div style={{ fontSize: 11, color: 'var(--ink-3)', fontStyle: 'italic', marginTop: 1 }}>{topics.length} topic{topics.length !== 1 ? 's' : ''} · cross-book threads</div>
        </div>
        <div style={{ marginLeft: 'auto', display: 'flex', gap: 6, alignItems: 'center', flexWrap: 'wrap' }}>
          <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search topics…" style={{ width: 170, padding: '6px 12px', fontSize: 12 }} />
          <button onClick={() => onCreate()} style={{ fontSize: 12, padding: '6px 16px', borderRadius: 7, background: 'var(--accent)', color: 'var(--paper-card)', border: 'none', cursor: 'pointer' }}>+ New topic</button>
        </div>
      </div>

      {/* Filter bar */}
      <div style={{ padding: '7px 22px', borderBottom: '1px solid var(--paper-3)', display: 'flex', gap: 6, alignItems: 'center', flexWrap: 'wrap', flexShrink: 0 }}>
        <span style={{ fontSize: 10, color: 'var(--ink-4)', fontFamily: 'var(--font-mono)', fontStyle: 'normal', textTransform: 'uppercase', letterSpacing: '0.06em' }}>Filter:</span>
        <select value={filterBook} onChange={e => setFilterBook(e.target.value)}
          style={{ fontSize: 11, padding: '3px 22px 3px 8px', borderRadius: 6, background: 'var(--paper-2)', color: 'var(--ink-2)', border: '1px solid var(--paper-3)' }}>
          <option value="all">All books</option>
          {books.map(b => <option key={b.id} value={b.id}>{b.title}</option>)}
        </select>
        <label style={{ display: 'flex', alignItems: 'center', gap: 5, fontSize: 11, color: 'var(--ink-3)', cursor: 'pointer' }}>
          <input type="checkbox" checked={showEmpty} onChange={e => setShowEmpty(e.target.checked)} style={{ width: 13, height: 13 }} />
          Show empty topics
        </label>
      </div>

      <div style={{ flex: 1, overflowY: 'auto', padding: '18px 22px' }}>
        {suggestions.length > 0 && (
          <TopicSuggestions suggestions={suggestions} thoughts={thoughts} books={books} onConfirm={onConfirmSuggestion} onDismiss={onDismiss} />
        )}

        {roots.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '60px 0', color: 'var(--ink-4)', fontStyle: 'italic', fontSize: 14 }}>
            {search ? 'No subjects match the current search. your search.' : 'No topic pages yet.'}
          </div>
        ) : (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(260px, 1fr))', gap: 10 }}>
            {roots.map(topic => {
              const children = getChildren(topic.id);
              return (
                <div key={topic.id} style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
                  <TopicCard topic={topic} thoughts={thoughts} books={books} onSelect={onSelect}>
                    {children.length > 0 ? children.map(c => <TopicCard key={c.id} topic={c} thoughts={thoughts} books={books} onSelect={onSelect} />) : null}
                  </TopicCard>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}
